
const express = require("express");
const cors = require("cors");
const mongoose = require("mongoose");

const app = express();
const PORT = 5000;

app.use(cors());
app.use(express.json());

// MongoDB connection
mongoose
  .connect("mongodb://127.0.0.1:27017/route_share")
  .then(() => console.log("MongoDB connected successfully"))
  .catch((error) => console.error("MongoDB connection error:", error));

// ORDER MODEL
const orderSchema = new mongoose.Schema(
  {
    customer: { type: String, required: true },
    pickup: { type: String, required: true },
    delivery: { type: String, required: true },
    package: { type: String, default: "Standard" },
    status: { type: String, default: "Order Confirmed" },
    driverId: { type: String, default: "" },
    driverName: { type: String, default: "" }
  },
  { timestamps: true }
);

const Order = mongoose.model("Order", orderSchema);

// DRIVER MODEL
const driverSchema = new mongoose.Schema(
  {
    name: { type: String, required: true },
    phone: { type: String, default: "" },
    vehicle: { type: String, default: "" },
    status: { type: String, default: "Available" }
  },
  { timestamps: true }
);

const Driver = mongoose.model("Driver", driverSchema);

// HOME
app.get("/", (req, res) => {
  res.send("RouteShare Backend is running!");
});

// GET ALL ORDERS
app.get("/api/orders", async (req, res) => {
  try {
    const orders = await Order.find().sort({ createdAt: -1 });
    res.json(orders.map((order) => ({
      ...order.toObject(),
      id: order._id.toString()
    })));
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

// CREATE ORDER
app.post("/api/orders", async (req, res) => {
  try {
    const { customer, pickup, delivery, package: packageType } = req.body;

    if (!customer || !pickup || !delivery) {
      return res.status(400).json({
        message: "Customer, pickup and delivery are required."
      });
    }

    const order = await Order.create({
      customer,
      pickup,
      delivery,
      package: packageType || "Standard"
    });

    res.status(201).json({
      ...order.toObject(),
      id: order._id.toString()
    });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

// GET SINGLE ORDER
app.get("/api/orders/:id", async (req, res) => {
  try {
    const order = await Order.findById(req.params.id);

    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    res.json({ ...order.toObject(), id: order._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// UPDATE ORDER STATUS
app.patch("/api/orders/:id/status", async (req, res) => {
  try {
    const order = await Order.findByIdAndUpdate(
      req.params.id,
      { status: req.body.status },
      { new: true, runValidators: true }
    );

    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    res.json({ ...order.toObject(), id: order._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// UPDATE ORDER
app.patch("/api/orders/:id", async (req, res) => {
  try {
    const allowed = ["customer", "pickup", "delivery", "package", "status"];
    const updates = {};

    for (const field of allowed) {
      if (req.body[field] !== undefined) {
        updates[field] = req.body[field];
      }
    }

    const order = await Order.findByIdAndUpdate(
      req.params.id,
      updates,
      { new: true, runValidators: true }
    );

    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    res.json({ ...order.toObject(), id: order._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// DELETE ORDER
app.delete("/api/orders/:id", async (req, res) => {
  try {
    const order = await Order.findByIdAndDelete(req.params.id);

    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    if (order.driverId) {
      await Driver.findByIdAndUpdate(order.driverId, {
        status: "Available"
      });
    }

    res.json({ message: "Order deleted successfully" });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// GET ALL DRIVERS
app.get("/api/drivers", async (req, res) => {
  try {
    const drivers = await Driver.find().sort({ createdAt: -1 });

    res.json(drivers.map((driver) => ({
      ...driver.toObject(),
      id: driver._id.toString()
    })));
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

// ADD DRIVER
app.post("/api/drivers", async (req, res) => {
  try {
    const { name, phone, vehicle } = req.body;

    if (!name) {
      return res.status(400).json({ message: "Driver name is required." });
    }

    const driver = await Driver.create({
      name,
      phone: phone || "",
      vehicle: vehicle || ""
    });

    res.status(201).json({
      ...driver.toObject(),
      id: driver._id.toString()
    });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

// UPDATE DRIVER
app.patch("/api/drivers/:id", async (req, res) => {
  try {
    const allowed = ["name", "phone", "vehicle", "status"];
    const updates = {};

    for (const field of allowed) {
      if (req.body[field] !== undefined) {
        updates[field] = req.body[field];
      }
    }

    const driver = await Driver.findByIdAndUpdate(
      req.params.id,
      updates,
      { new: true, runValidators: true }
    );

    if (!driver) {
      return res.status(404).json({ message: "Driver not found" });
    }

    res.json({ ...driver.toObject(), id: driver._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// DELETE DRIVER
app.delete("/api/drivers/:id", async (req, res) => {
  try {
    const activeOrder = await Order.findOne({
      driverId: req.params.id,
      status: { $ne: "Delivered" }
    });

    if (activeOrder) {
      return res.status(400).json({
        message: "Unassign the driver's active order before deleting."
      });
    }

    const driver = await Driver.findByIdAndDelete(req.params.id);

    if (!driver) {
      return res.status(404).json({ message: "Driver not found" });
    }

    res.json({ message: "Driver deleted successfully" });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// ASSIGN DRIVER
app.post("/api/orders/:id/assign", async (req, res) => {
  try {
    const { driverId } = req.body;

    const order = await Order.findById(req.params.id);
    const driver = await Driver.findById(driverId);

    if (!order || !driver) {
      return res.status(404).json({
        message: "Order or driver not found."
      });
    }

    if (driver.status === "Assigned" && order.driverId !== driverId) {
      return res.status(400).json({
        message: "Driver is already assigned."
      });
    }

    if (order.driverId && order.driverId !== driverId) {
      await Driver.findByIdAndUpdate(order.driverId, {
        status: "Available"
      });
    }

    order.driverId = driver._id.toString();
    order.driverName = driver.name;
    order.status = "Driver Assigned";

    await order.save();

    driver.status = "Assigned";
    await driver.save();

    res.json({
      order: { ...order.toObject(), id: order._id.toString() },
      driver: { ...driver.toObject(), id: driver._id.toString() }
    });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// UNASSIGN DRIVER
app.post("/api/orders/:id/unassign", async (req, res) => {
  try {
    const order = await Order.findById(req.params.id);

    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    if (order.driverId) {
      await Driver.findByIdAndUpdate(order.driverId, {
        status: "Available"
      });
    }

    order.driverId = "";
    order.driverName = "";
    order.status = "Order Confirmed";

    await order.save();

    res.json({ ...order.toObject(), id: order._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// TRACKING
app.get("/api/tracking", async (req, res) => {
  try {
    const orders = await Order.find({
      status: { $ne: "Delivered" }
    });

    res.json(orders.map((order) => ({
      ...order.toObject(),
      id: order._id.toString()
    })));
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

app.get("/api/tracking/:id", async (req, res) => {
  try {
    const order = await Order.findById(req.params.id);

    if (!order) {
      return res.status(404).json({ message: "Tracking order not found" });
    }

    res.json({ ...order.toObject(), id: order._id.toString() });
  } catch (error) {
    res.status(400).json({ message: error.message });
  }
});

// BASIC ROUTE AND ANALYTICS ENDPOINTS
app.get("/api/routes", (req, res) => res.json([]));
app.get("/api/shared-routes", (req, res) => res.json([]));
app.get("/api/route-score", (req, res) => res.json({ score: 0 }));

app.get("/api/analytics", async (req, res) => {
  try {
    const totalOrders = await Order.countDocuments();
    const delivered = await Order.countDocuments({ status: "Delivered" });
    const totalDrivers = await Driver.countDocuments();

    res.json({
      totalOrders,
      delivered,
      totalDrivers,
      activeDeliveries: await Order.countDocuments({
        status: { $in: ["Picked Up", "Out for Delivery"] }
      })
    });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

app.get("/api/reports", (req, res) => {
  res.json({ message: "RouteShare reports endpoint" });
});

// START SERVER
app.listen(PORT, () => {
  console.log(`RouteShare backend running at http://localhost:${PORT}`);
});
